def gen(rng):
    CAP = 5000
    def tree(n, mode):
        par = [-1] * n
        dep = [0] * n
        for i in range(1, n):
            while True:
                if mode == 'rand':
                    p = rng.randrange(i)
                elif mode == 'path':
                    p = i - 1
                elif mode == 'win':
                    p = rng.randrange(max(0, i - 30), i)
                elif mode == 'star':
                    p = 0
                else:
                    p = rng.randrange(max(0, i - 3), i)
                if dep[p] < CAP:
                    break
                mode = 'rand'
            par[i] = p
            dep[i] = dep[p] + 1
        return par
    def values(n, par, kind):
        if kind == 'ones':
            return [1] * n
        if kind == 'twos':
            return [2] * n
        if kind == 'r123':
            return [rng.randint(1, 3) for _ in range(n)]
        if kind == 'r12':
            return [rng.randint(1, 2) for _ in range(n)]
        if kind == 'sparse':
            v = [1] * n
            for val in (2, 3):
                for _ in range(rng.randint(1, 3)):
                    v[rng.randrange(n)] = val
            return v
        if kind == 'split':
            r = rng.randrange(1, n)
            mark = [False] * n
            mark[r] = True
            for i in range(1, n):
                if mark[par[i]]:
                    mark[i] = True
            return [rng.choice((1, 2)) if mark[i] else rng.choice((1, 3)) for i in range(n)]
        raise ValueError(kind)
    def fmt(n, vals, par):
        edges = [(par[i], i) for i in range(1, n)]
        rng.shuffle(edges)
        edges = [(v, u) if rng.random() < 0.5 else (u, v) for (u, v) in edges]
        return f"{n}\n" + ' '.join(map(str, vals)) + "\n" + '\n'.join(f"{u} {v}" for u, v in edges)
    def make(n, mode, kind):
        par = tree(n, mode)
        return fmt(n, values(n, par, kind), par)
    tests = [
        "2\n1 1\n0 1", "2\n2 3\n0 1", "3\n3 1 2\n0 1\n1 2",
        "4\n1 1 2 3\n0 1\n1 2\n2 3", "4\n1 2 3 2\n0 1\n0 2\n0 3",
        make(6, 'path', 'ones'), make(6, 'star', 'twos'),
    ]
    for n in (3, 4, 5, 6, 8, 10, 12, 15, 20, 30):
        for kind in ('r123', 'r12', 'sparse', 'split', 'r123'):
            tests.append(make(n, rng.choice(('rand', 'path', 'win', 'star', 'near')), kind))
    N = 10**5
    tests.append(make(N, 'win', 'sparse'))
    tests.append(make(N, 'win', 'split'))
    tests.append(make(N, 'rand', 'ones'))
    tests.append(make(N, 'near', 'split'))
    tests.append(make(N, 'rand', 'r123'))
    tests.append(make(N, 'star', 'sparse'))
    tests.append(make(5001, 'path', 'sparse'))
    tests.append(make(5001, 'path', 'split'))
    tests.append(make(N, 'path', 'sparse'))
    return tests
